const HEADER = 'id,date,category,amount';

export function exportAllCsv(records = []) {
  if (!Array.isArray(records)) {
    throw new TypeError('INVALID_RECORDS');
  }
  const sorted = [...records].sort((a, b) => String(a.date).localeCompare(String(b.date)));
  const rows = sorted.map(r => `${r.id},${r.date},${r.category},${r.amount}`);
  return [HEADER, ...rows].join('\n');
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {exportAllCsv} from '../src/exporter.mjs';

test('exportAllCsv sorts by date and formats rows', () => {
  const list = [
    {id: 2, date: '2026-11-05', category: 'food', amount: 35},
    {id: 1, date: '2026-10-20', category: 'book', amount: 50}
  ];
  assert.equal(
    exportAllCsv(list),
    'id,date,category,amount\n1,2026-10-20,book,50\n2,2026-11-05,food,35'
  );
});

export function addTodo(todos = [], {id, title, tags = []}) {
  return [...todos, {id, title: String(title).trim(), tags: [...tags], done: false}];
}

export function toggleTodo(todos = [], id) {
  return todos.map(item => (item.id === id ? {...item, done: !item.done} : item));
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {addTodo, toggleTodo} from '../src/todo-store.mjs';

test('addTodo and toggleTodo keep immutability', () => {
  const list1 = addTodo([], {id: 't1', title: 'Read docs', tags: ['work']});
  const list2 = toggleTodo(list1, 't1');
  assert.equal(list1[0].done, false);
  assert.equal(list2[0].done, true);
});
